/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{

  /* USER CODE BEGIN 1 */
	Radio_Scaled.pitch = 0;	// Initialize radio values to ensure no undefined behavior on startup
	Radio_Scaled.roll = 0;
	Radio_Scaled.throttle = 0;
	Radio_Scaled.yaw = 0;
	Radio_Scaled.armed = 0;
  /* USER CODE END 1 */

  /* MCU Configuration--------------------------------------------------------*/

  /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
  HAL_Init();

  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* Configure the system clock */
  SystemClock_Config();

  /* USER CODE BEGIN SysInit */

  /* USER CODE END SysInit */

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_DMA_Init();
  MX_ADC1_Init();
  MX_I2C1_Init();
  MX_SPI1_Init();
  MX_SPI3_Init();
  MX_TIM1_Init();
  MX_TIM2_Init();
  MX_USART2_UART_Init();
  MX_USART3_UART_Init();
  MX_TIM3_Init();
  /* USER CODE BEGIN 2 */
  HAL_TIM_Base_Start_IT(&htim3);	// TIM3 has a period of 200ms and is used to blink LEDs for status.

  HAL_TIM_Base_Start(MOTOR_TIMER);
  HAL_TIM_PWM_Start(MOTOR_TIMER, MOTOR_FL);
  HAL_TIM_PWM_Start(MOTOR_TIMER, MOTOR_FR);
  HAL_TIM_PWM_Start(MOTOR_TIMER, MOTOR_BL);
  HAL_TIM_PWM_Start(MOTOR_TIMER, MOTOR_BR);


  __HAL_SPI_ENABLE(&hspi1);
  // LED testing sequence. Additionally, it gives time for everything to power up.
  LED_Test_Sequence();

  IMU_Test();		// Test the IMU
  if(IMU_Status == IMU_FAULTY){
  	sensor_status = FATAL;
  } else {
  	sensor_status = MANUAL_ONLY;
  	IMU_Init();
  }

  GPS_Init();
  Radio_Init();

  /* USER CODE END 2 */

  /* Infinite loop */
  /* USER CODE BEGIN WHILE */
  while (1)
  {
    /* USER CODE END WHILE */

    /* USER CODE BEGIN 3 */
  }
  /* USER CODE END 3 */
}

